import org.rabochaya.projects.*;import org.rabochaya.maptests.OziFixtures;import java.io.*;import java.nio.charset.StandardCharsets;
public final class OziTests {
 static int n;static void ck(boolean ok){n++;if(!ok)throw new AssertionError("Ozi "+n);}static OziCalibration read(String text)throws IOException{return OziCalibration.read(new ByteArrayInputStream(text.getBytes(StandardCharsets.UTF_8)),"map.png",35,33);}static void reject(String text)throws IOException{boolean refused=false;try{read(text);}catch(IOException e){refused=true;}ck(refused);}
 public static void main(String[] args)throws Exception{
  for(double[] matrix:new double[][]{{.01,.004,2,.002,-.01,1},{0,-.01,2,-.01,0,1},{-.01,0,-2,0,.01,-1}}){String text=OziFixtures.map("map.png",35,33,matrix);OziCalibration c=read(text);ck(c.controls==4&&c.imageName.equals("map.png"));for(int[] p:new int[][]{{0,0},{1,1},{16,16},{34,32}}){double x=p[0]+.5,y=p[1]+.5;long packed=c.transform.cellModel(matrix[0]*x+matrix[1]*y+matrix[2],matrix[3]*x+matrix[4]*y+matrix[5]);ck(packed==((long)p[1]<<32|p[0]));}ck(c.transform.cellModel(matrix[0]*-1+matrix[2],matrix[3]*-1+matrix[5])==-1);ck(c.transform.pixelsPerWorldUnit()>0);ck(read("\ufeff"+text.replace("\n","\r\n")).controls==4);}
  String good=OziFixtures.map("map.png",35,33,new double[]{.01,.004,2,.002,-.01,1});OziCalibration c=read(good);ck(Math.abs(c.transform.west-2)<1e-10&&Math.abs(c.transform.east-2.482)<1e-10);ck(Math.abs(c.transform.south-.67)<1e-10&&Math.abs(c.transform.north-1.07)<1e-10);ck(read(good.replace("map.png","C:\\maps\\MAP.PNG")).controls==4);ck(read(good+"MMPNUM,4\nMMPXY,1,0,0\nMMPXY,2,35,0\nMMPXY,3,35,33\nMMPXY,4,0,33\n").controls==4);
  for(String bad:new String[]{good.replace("OziExplorer","Other"),good.replace("WGS 84,WGS 84","Pulkovo 1942,WGS 84"),good.replace("0.0000,0.0000","1.0000,0.0000"),good.replace("Latitude/Longitude","Mercator"),good.replace("PolyCal,No","PolyCal,Yes"),good.replace("AutoCalOnly,No","AutoCalOnly,Yes"),good.replace("BSBUseWPX,No","BSBUseWPX,Yes"),good.replace("Version 2.2","Version 9.9"),good.replace("AutoCalOnly,No","UnknownTransform,No"),good.replace("AutoCalOnly,No","PolyCal,No"),good.replace("MSF,1","MSF,2"),good.replace("IWH,Map Image Width/Height,35,33","IWH,Map Image Width/Height,36,33"),good.replace("map.png","other.png"),good.replace("map.png","../map.png"),good.replace("map.png","https://host/map.png"),good.replace("map.png","\\\\host\\map.png"),good.replace("Point04","Point03"),good.replace("Point01,xy,0.0,0.0","Point01,xy,-1,0"),good.replace("Point01,xy,0.0,0.0","Point01,xy,NaN,0"),good.replace(",N,",",Q,"),good.replace(",deg,",",rad,"),good.replace(",in,",",ex,"),good.replace("Projection Setup,,,,,,,,,,","Projection Setup,1"),good+"MSF,1\n",good+"MMPNUM,4\nMMPXY,1,0,0\nMMPXY,2,34,0\nMMPXY,3,34,32\nMMPXY,4,0,32\n",good+"MMPNUM,4\nMMPXY,1,0,0\n",good+OziFixtures.point(5,17,17,2.5,.7),good+"Point31,xy,1,1,in,deg,1,60,N,2,0,E,grid,,,,N\n",good+"Point31,xy,1,1,in,deg,90,1,N,2,0,E,grid,,,,N\n",good+"Point31,xy,1,1,in,deg,1,1,N,180,1,E,grid,,,,N\n"})reject(bad);
  reject(OziFixtures.map("map.png",35,33,new double[]{.01,.01,2,.01,.01,1}));String base=good.substring(0,good.indexOf("Point01"));reject(base+OziFixtures.point(1,0,0,2,1)+OziFixtures.point(2,1,1,2.01,.99)+OziFixtures.point(3,2,2,2.02,.98));reject(base+OziFixtures.point(1,0,0,2,1)+OziFixtures.point(2,1,1,2.01,.99));StringBuilder many=new StringBuilder(base);for(int i=1;i<=31;i++)many.append(OziFixtures.point(i,i%35,i%33,2+i*.01,1-i*.01));reject(many.toString());reject(good+"\0");reject(good+new String(new char[OziCalibration.MAX_BYTES]).replace('\0','x'));reject(good+new String(new char[4097]).replace('\0','x'));boolean failed=false;try{OziCalibration.read(new ByteArrayInputStream(new byte[]{(byte)0xff}),"map.png",35,33);}catch(IOException e){failed=true;}ck(failed);String russian=good.replace("map.png","картаЁ.png");byte[] cp=russian.getBytes("windows-1251");
  ck(OziCalibration.read(new ByteArrayInputStream(cp),"картаЁ.png",35,33,OziCalibration.Encoding.WINDOWS1251).controls==4);
  ck(OziCalibration.read(new ByteArrayInputStream(russian.getBytes(StandardCharsets.UTF_8)),"картаЁ.png",35,33).imageName.equals("картаЁ.png"));
  byte[] name={ (byte)0xea,(byte)0xe0,(byte)0xf0,(byte)0xf2,(byte)0xe0,(byte)0xa8 };
  ck(new String(name,"windows-1251").equals("картаЁ"));
  byte[] controlName=good.replace("map.png","map~.png").getBytes(StandardCharsets.US_ASCII);for(int i=0;i<controlName.length;i++)if(controlName[i]==126)controlName[i]=(byte)0x98;
  for(int variant=0;variant<4;variant++){boolean refused=false;try{if(variant==0)OziCalibration.read(new ByteArrayInputStream(cp),"картаЁ.png",35,33);else if(variant==1)OziCalibration.read(new ByteArrayInputStream(russian.getBytes(StandardCharsets.UTF_8)),"картаЁ.png",35,33,OziCalibration.Encoding.WINDOWS1251);else if(variant==2)OziCalibration.read(new ByteArrayInputStream(cp),"картаЁ.png",35,33,null);else OziCalibration.read(new ByteArrayInputStream(controlName),"map~.png",35,33,OziCalibration.Encoding.WINDOWS1251);}catch(IOException e){refused=true;}ck(refused);}
  System.out.println("Ozi: "+n+" assertions passed");
 }
}
